const PATTERN = [1.12, 1.04, 1.09, 1.15, 1.06, 1.11, 1.05, 1.13];
const oyFor = (scale) => scale >= 1.12 ? 33 : scale <= 1.01 ? 44 : 38;
const SHOTS = (() => {
  const shots = [];
  let prevScale = 1.03;
  let prevOy = 40;
  let pi = 0;
  for (let i = 0; i < SPANS.length; i++) {
    const s = SPANS[i];
    const sectionStart = i === 0 || SPANS[i - 1].section !== s.section;
    let scale;
    if (sectionStart) {
      scale = 1;
      pi = 0;
    } else {
      scale = PATTERN[pi % PATTERN.length];
      pi += 1;
    }
    const oy = oyFor(scale);
    shots.push({
      startF: Math.round(s.cutStart * timing_FPS),
      endF: Math.round(s.cutEnd * timing_FPS),
      scale,
      oy,
      prevScale,
      prevOy
    });
    prevScale = scale;
    prevOy = oy;
  }
  return shots;
})();
const shots_TR = 22;
const easeInOutQuad = (p) => p < 0.5 ? 2 * p * p : 1 - Math.pow(-2 * p + 2, 2) / 2;
const shotAt = (cutFrame) => {
  let idx = 0;
  for (let i = 0; i < SHOTS.length; i++) {
    if (cutFrame >= SHOTS[i].startF) idx = i;
    else break;
  }
  const shot = SHOTS[idx];
  const local = cutFrame - shot.startF;
  let scale;
  let oy;
  if (local < shots_TR) {
    const e = easeInOutQuad(Math.max(0, local) / shots_TR);
    scale = shot.prevScale + (shot.scale - shot.prevScale) * e;
    oy = shot.prevOy + (shot.oy - shot.prevOy) * e;
  } else {
    const dur = Math.max(1, shot.endF - shot.startF - shots_TR);
    const held = local - shots_TR;
    scale = shot.scale + Math.sin(held / dur * Math.PI) * 0.012;
    oy = shot.oy;
  }
  return { scale: Math.max(1, scale), ox: 50, oy };
};

